/**
 * Test fixture — production reads `harvest-http.ts` (POE-286).
 * Harvest server data fixture adapter — the mock behind `LoadHarvestFamilies`.
 *
 * Tiers come from `harvest-tiers.json`, generated by `cmd/harvest-tiers`
 * through `internal/price/tier` with no price cutoff (P49), keyed by family id;
 * a family without an entry is served with `tiers: null`. Tiers are derived
 * from exchange prices, so the server keys them to the price hour they were
 * computed on; the adapter stamps the exchange fixture's `priceHour`. Both
 * horizons serve the same fixture. Families without logged weights stay in
 * the list with `weights: null`.
 */
import exchange from '../__fixtures__/exchange.json';
import harvest from '../__fixtures__/harvest.json';
import harvestTiers from '../__fixtures__/harvest-tiers.json';
import type { HarvestFamily, HarvestFamilyData, LifeforceColour, LoadHarvestFamilies } from '../seam';

interface FixtureFamily {
	id: string;
	label: string;
	lifeforce?: string;
	rerollCost?: number;
	weights: HarvestFamily['weights'];
	_note?: string;
}

type FixtureTiers = Omit<NonNullable<HarvestFamily['tiers']>, 'priceHour'>;

/** Own-key lookup: a family id is foreign data and may be `constructor`. */
function tiersOf(id: string): FixtureTiers | null {
	const families: Record<string, FixtureTiers> = harvestTiers.families;
	return Object.hasOwn(families, id) ? families[id] : null;
}

function toFamily(f: FixtureFamily): HarvestFamily {
	const tiers = tiersOf(f.id);
	return {
		id: f.id,
		label: f.label,
		lifeforce: (f.lifeforce as LifeforceColour | undefined) ?? null,
		rerollCost: f.rerollCost ?? null,
		weights: f.weights
			? { sample: { ...f.weights.sample }, types: f.weights.types.map((t) => ({ ...t })) }
			: null,
		tiers: tiers
			? {
					boundariesChaos: [...tiers.boundariesChaos],
					names: [...tiers.names],
					topBoundaryChaos: tiers.topBoundaryChaos,
					byItem: { ...tiers.byItem },
					priceHour: exchange.priceHour
				}
			: null,
		note: f._note ?? null
	};
}

export const loadHarvestFamilies: LoadHarvestFamilies = async () => {
	const data: HarvestFamilyData = {
		warm: true,
		families: harvest.families.map(toFamily)
	};
	return data;
};
